/*
 * Based on the upstream workspace:template action from Backstage:
 * https://github.com/backstage/backstage/blob/master/plugins/scaffolder-backend/src/scaffolder/actions/builtin/fetch/workspaceTemplate.ts
 *
 * The upstream action exists in the repo but is not exported from the package.
 * This is a simplified reimplementation using nunjucks directly.
 */

import { createTemplateAction } from '@backstage/plugin-scaffolder-node';
import { resolveSafeChildPath } from '@backstage/backend-plugin-api';
import nunjucks from 'nunjucks';
import fs from 'fs-extra';
import globby from 'globby';
import path from 'node:path';

export const intropyWorkspaceTemplateExamples = [
  {
    description: 'Template files from a skeleton directory',
    example: `
steps:
  - id: template
    action: intropy:workspace:template
    input:
      sourcePath: ./skeleton
      targetPath: ./output
      values:
        name: my-service
        description: A new service
`,
  },
];

/**
 * Creates the intropy:workspace:template action.
 *
 * This action templates files from a source path in the workspace
 * to a target path, replacing nunjucks variables with provided values.
 *
 * Similar to fetch:template but operates on files already in the workspace.
 */
export function createIntropyWorkspaceTemplateAction() {
  return createTemplateAction({
    id: 'intropy:workspace:template',
    description:
      'Templates files from sourcePath in the workspace to targetPath using nunjucks.',
    examples: intropyWorkspaceTemplateExamples,
    schema: {
      input: {
        sourcePath: z => z.string().describe('Source path in workspace'),
        targetPath: z => z.string().describe('Target path in workspace'),
        values: z => z.record(z.any()).optional().describe('Template values'),
      },
    },
    async handler(ctx) {
      const { sourcePath, targetPath, values = {} } = ctx.input;

      const sourceDir = resolveSafeChildPath(ctx.workspacePath, sourcePath);
      const targetDir = resolveSafeChildPath(ctx.workspacePath, targetPath);

      ctx.logger.info(`Templating from ${sourcePath} to ${targetPath}`);

      const env = new nunjucks.Environment(
        new nunjucks.FileSystemLoader(sourceDir),
        {
          autoescape: false,
          noCache: true,
          tags: {
            variableStart: '${{',
            variableEnd: '}}',
          },
        },
      );

      const context = { values };

      const files = await globby('**/*', {
        cwd: sourceDir,
        dot: true,
        onlyFiles: true,
      });

      for (const file of files) {
        const srcPath = path.join(sourceDir, file);
        const renderedFile = env.renderString(file, context);
        const destPath = path.join(targetDir, renderedFile);

        await fs.ensureDir(path.dirname(destPath));

        const content = await fs.readFile(srcPath, 'utf-8');
        const rendered = env.renderString(content, context);
        await fs.writeFile(destPath, rendered, 'utf-8');
      }

      ctx.logger.info(`Completed templating to ${targetPath}`);
    },
  });
}

