import { createBackendModule } from '@backstage/backend-plugin-api';
import { scaffolderActionsExtensionPoint } from '@backstage/plugin-scaffolder-node';
import { createIntropyWorkspaceTemplateAction } from './actions/intropyWorkspaceTemplate';

export const scaffolderIntropyModule = createBackendModule({
  pluginId: 'scaffolder',
  moduleId: 'intropy-actions',
  register(env) {
    env.registerInit({
      deps: {
        scaffolder: scaffolderActionsExtensionPoint,
      },
      async init({ scaffolder }) {
        scaffolder.addActions(createIntropyWorkspaceTemplateAction());
      },
    });
  },
});
