import nunjucks from 'nunjucks';
import fs from 'fs-extra';
import os from 'os';
import path from 'path';
import globby from 'globby';

describe('intropy:workspace:template', () => {
  describe('nunjucks templating with ${{ }} syntax', () => {
    it('should template file names with ${{ values.xxx }} syntax', () => {
      const env = new nunjucks.Environment(null, {
        autoescape: false,
        tags: {
          variableStart: '${{',
          variableEnd: '}}',
        },
      });

      const context = { values: { projectName: 'MyService' } };
      const input = '${{values.projectName}}.csproj';
      const output = env.renderString(input, context);

      expect(output).toBe('MyService.csproj');
    });

    it('should template nested paths with ${{ values.xxx }} syntax', () => {
      const env = new nunjucks.Environment(null, {
        autoescape: false,
        tags: {
          variableStart: '${{',
          variableEnd: '}}',
        },
      });

      const context = { values: { entityName: 'Customer' } };
      const input = 'Models/${{values.entityName}}Payload.cs';
      const output = env.renderString(input, context);

      expect(output).toBe('Models/CustomerPayload.cs');
    });

    it('should template file content with ${{ values.xxx }} syntax', () => {
      const env = new nunjucks.Environment(null, {
        autoescape: false,
        tags: {
          variableStart: '${{',
          variableEnd: '}}',
        },
      });

      const context = { values: { name: 'my-app', version: '1.0.0' } };
      const input = 'name: ${{ values.name }}\nversion: ${{ values.version }}';
      const output = env.renderString(input, context);

      expect(output).toBe('name: my-app\nversion: 1.0.0');
    });

    it('should handle multiple template values in file names', () => {
      const env = new nunjucks.Environment(null, {
        autoescape: false,
        tags: {
          variableStart: '${{',
          variableEnd: '}}',
        },
      });

      const context = { values: { prefix: 'Test', name: 'Component' } };
      const input = '${{values.prefix}}_${{values.name}}.ts';
      const output = env.renderString(input, context);

      expect(output).toBe('Test_Component.ts');
    });

    it('should preserve files without template syntax', () => {
      const env = new nunjucks.Environment(null, {
        autoescape: false,
        tags: {
          variableStart: '${{',
          variableEnd: '}}',
        },
      });

      const context = { values: {} };
      const input = 'static-file.txt';
      const output = env.renderString(input, context);

      expect(output).toBe('static-file.txt');
    });
  });

  describe('globby file discovery', () => {
    let tempDir: string;

    beforeEach(async () => {
      tempDir = await fs.mkdtemp(
        path.join(os.tmpdir(), 'intropy-template-test-'),
      );
    });

    afterEach(async () => {
      await fs.remove(tempDir);
    });

    it('should find files with ${{ }} in their names', async () => {
      await fs.ensureDir(path.join(tempDir, 'src'));
      await fs.writeFile(
        path.join(tempDir, 'src', '${{values.name}}.cs'),
        'content',
      );
      await fs.writeFile(path.join(tempDir, 'static.txt'), 'content');

      const files = await globby('**/*', {
        cwd: tempDir,
        dot: true,
        onlyFiles: true,
      });

      expect(files).toContain('src/${{values.name}}.cs');
      expect(files).toContain('static.txt');
    });
  });
});

