/*
 * Hi!
 *
 * Note that this is an EXAMPLE Backstage backend. Please check the README.
 *
 * Happy hacking!
 */

import { createBackend } from '@backstage/backend-defaults';
import { groupTransformer } from './groupTransformer';
import { microsoftGraphOrgEntityProviderTransformExtensionPoint } from '@backstage/plugin-catalog-backend-module-msgraph';
import { createBackendModule } from '@backstage/backend-plugin-api';
import { scaffolderIntropyModule } from './scaffolder/module';
import { permissionPolicyModule } from './permissions/module';
import {
  gitlabPlugin,
  catalogPluginGitlabFillerProcessorModule,
} from '@immobiliarelabs/backstage-plugin-gitlab-backend';

const backend = createBackend();

backend.add(import('@backstage/plugin-app-backend'));
backend.add(import('@backstage/plugin-proxy-backend'));

// Add GitLab auth provider
backend.add(import('@backstage/plugin-auth-backend-module-gitlab-provider'));

backend.add(import('@integrio/backstage-plugin-agent-skills-backend'));

backend.add(import('@backstage/plugin-mcp-actions-backend'));
backend.add(import('@integrio/backstage-plugin-techdocs-mcp-tool'));
backend.add(import('@integrio/backstage-plugin-software-catalog-mcp-tool'));
backend.add(import('@integrio/backstage-plugin-techdocs-retrieval-backend'));

// scaffolder plugin
backend.add(import('@backstage/plugin-scaffolder-backend'));
backend.add(import('@backstage/plugin-scaffolder-backend-module-gitlab'));
backend.add(import('@backstage/plugin-scaffolder-backend-module-github'));
backend.add(import('@roadiehq/scaffolder-backend-module-utils'));
backend.add(
  import('@backstage/plugin-scaffolder-backend-module-notifications'),
);
backend.add(scaffolderIntropyModule);

backend.add(import('@digitalist-open-cloud/backstage-plugin-harbor-backend'));

// techdocs plugin
backend.add(import('@backstage/plugin-techdocs-backend'));

backend.add(import('@kyverno/backstage-plugin-policy-reporter-backend'));

// auth plugin
backend.add(import('@backstage/plugin-auth-backend'));
// See https://backstage.io/docs/backend-system/building-backends/migrating#the-auth-plugin
backend.add(import('@backstage/plugin-auth-backend-module-microsoft-provider'));
// See https://backstage.io/docs/auth/guest/provider
backend.add(import('@backstage/plugin-auth-backend-module-guest-provider'));

// catalog plugin
backend.add(import('@backstage/plugin-catalog-backend'));
backend.add(
  import('@backstage/plugin-catalog-backend-module-scaffolder-entity-model'),
);

// See https://backstage.io/docs/features/software-catalog/configuration#subscribing-to-catalog-errors
backend.add(import('@backstage/plugin-catalog-backend-module-logs'));

backend.add(import('@roadiehq/backstage-plugin-argo-cd-backend'));

// permission plugin
backend.add(import('@backstage/plugin-permission-backend'));
backend.add(
  createBackendModule({
    pluginId: 'catalog',
    moduleId: 'microsoft-graph-extensions',
    register(env) {
      env.registerInit({
        deps: {
          microsoftGraphTransformers:
            microsoftGraphOrgEntityProviderTransformExtensionPoint,
        },
        async init({ microsoftGraphTransformers }) {
          microsoftGraphTransformers.setGroupTransformer(groupTransformer);
        },
      });
    },
  }),
);
backend.add(import('@backstage/plugin-catalog-backend-module-msgraph/alpha'));
// Custom permission policy: restricts catalog entity visibility to owned entities
backend.add(permissionPolicyModule);

// search plugin
backend.add(import('@backstage/plugin-search-backend'));
backend.add(import('@backstage-community/search-backend-module-adr'));

// search engine
// See https://backstage.io/docs/features/search/search-engines
backend.add(import('@backstage/plugin-search-backend-module-pg'));

// search collators
backend.add(import('@backstage/plugin-search-backend-module-catalog'));
backend.add(import('@backstage/plugin-search-backend-module-techdocs'));

// kubernetes plugin
backend.add(import('@backstage/plugin-kubernetes-backend'));

// notifications and signals plugins
backend.add(import('@backstage/plugin-notifications-backend'));
backend.add(import('@backstage/plugin-signals-backend'));

backend.add(import('@backstage-community/plugin-adr-backend'));

backend.add(gitlabPlugin);
backend.add(catalogPluginGitlabFillerProcessorModule);

backend.start();

