2	import os from 'os';
3	import path from 'path';
4	import { createIntropyIntCreateAction } from './intropyIntCreate';
5	import { runIntropyCli, RunIntropyCliResult } from './runIntropyCli';
6	
7	jest.mock('./runIntropyCli');
8	const mockRun = runIntropyCli as jest.MockedFunction<typeof runIntropyCli>;
9	
10	function makeConfig(data: Record<string, any> = {}) {
11	  return {
12	    getOptionalString: (key: string) => {
13	      const value = key
14	        .split('.')
15	        .reduce<any>((cur, part) => cur?.[part], data);
16	      return typeof value === 'string' ? value : undefined;
17	    },
18	  } as any;
19	}
20	
21	describe('intropy:int:create', () => {
22	  let workspacePath: string;
23	  let tmpDir: string;
24	  let outputs: Record<string, unknown>;
25	
26	  const makeCtx = (input: Record<string, unknown>) => {
27	    outputs = {};
28	    return {
29	      input,
30	      workspacePath,
31	      logger: {
32	        info: jest.fn(),
33	        warn: jest.fn(),
34	        error: jest.fn(),
35	        debug: jest.fn(),
36	      },
37	      createTemporaryDirectory: jest.fn(async () => tmpDir),
38	      output: (key: string, value: unknown) => {
39	        outputs[key] = value;
40	      },
41	    } as any;
42	  };
43	
44	  // Default: the CLI succeeds and writes a CreateResult to the --output-json path.
45	  const succeedWith = (result: Record<string, unknown>) => {
46	    mockRun.mockImplementation(
47	      async ({ args }): Promise<RunIntropyCliResult> => {
48	        const idx = args.indexOf('--output-json');
49	        await fs.writeFile(args[idx + 1], JSON.stringify(result), 'utf8');
50	        return { exitCode: 0, stderrTail: [] };
51	      },
52	    );
53	  };
54	
55	  beforeEach(async () => {
56	    workspacePath = await fs.mkdtemp(path.join(os.tmpdir(), 'intropy-ws-'));
57	    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'intropy-tmp-'));
58	    mockRun.mockReset();
59	  });
60	
61	  afterEach(async () => {
62	    await fs.remove(workspacePath);
63	    await fs.remove(tmpDir);
64	  });
65	
66	  it('invokes the CLI with the expected argv and registers outputs', async () => {
67	    succeedWith({
68	      blueprint: 'dapr-minimal-api',
69	      version: 'v0.1.5',
70	      outputDir: path.join(workspacePath, 'output/my-api'),
71	    });
72	
73	    const action = createIntropyIntCreateAction({ config: makeConfig() });
74	    await action.handler(
75	      makeCtx({
76	        blueprint: 'hello-world',
77	        name: 'MyApi',
78	        targetPath: './output/my-api',
79	      }),
80	    );
81	
82	    const { command, args } = mockRun.mock.calls[0][0];
83	    expect(command).toBe('intropy');
84	    // Fixed prefix, in order.
85	    expect(args.slice(0, 3)).toEqual(['int', 'create', 'hello-world']);
86	    expect(args).toContain('--no-input');
87	    expect(args).toContain('--skip-install-skills');
88	    expect(args[args.indexOf('--name') + 1]).toBe('MyApi');
89	    expect(args[args.indexOf('--output') + 1]).toBe(
90	      path.join(workspacePath, 'output/my-api'),
91	    );
92	    // No values → no -f flag.
93	    expect(args).not.toContain('-f');
94	
95	    expect(outputs).toEqual({
96	      outputDir: path.normalize('output/my-api'),
97	      blueprintVersion: 'v0.1.5',
98	      blueprint: 'dapr-minimal-api',
99	    });
100	  });
101	
102	  it('writes nested values to a JSON file and passes it with -f', async () => {
103	    succeedWith({ outputDir: workspacePath, version: 'v1' });
104	
105	    const action = createIntropyIntCreateAction({ config: makeConfig() });
106	    await action.handler(
107	      makeCtx({
108	        blueprint: 'hello-world',
109	        name: 'MyApi',
110	        values: { nested: { a: 1 }, list: ['x', 'y'] },
111	      }),
112	    );
113	
114	    const { args } = mockRun.mock.calls[0][0];
115	    const valuesFile = args[args.indexOf('-f') + 1];
116	    expect(JSON.parse(await fs.readFile(valuesFile, 'utf8'))).toEqual({
117	      nested: { a: 1 },
118	      list: ['x', 'y'],
119	    });
120	  });
121	
122	  it('resolves the binary path from config when set', async () => {
123	    succeedWith({ outputDir: workspacePath, version: 'v1' });
124	
125	    const action = createIntropyIntCreateAction({
126	      config: makeConfig({ intropy: { cli: { path: '/opt/intropy' } } }),
127	    });
128	    await action.handler(makeCtx({ blueprint: 'hello-world', name: 'MyApi' }));
129	
130	    expect(mockRun.mock.calls[0][0].command).toBe('/opt/intropy');
131	  });
132	
133	  it('throws InputError on exit code 2', async () => {
134	    mockRun.mockResolvedValue({
135	      exitCode: 2,
136	      stderrTail: ['error: missing required parameter(s): name'],
137	    });
138	
139	    const action = createIntropyIntCreateAction({ config: makeConfig() });
140	    await expect(
141	      action.handler(makeCtx({ blueprint: 'hello-world', name: 'MyApi' })),
142	    ).rejects.toThrow(/missing required parameter/);
143	  });
144	
145	  it('throws a runtime error on other non-zero exit codes', async () => {
146	    mockRun.mockResolvedValue({
147	      exitCode: 1,
148	      stderrTail: ['error: could not download blueprint'],
149	    });
150	
151	    const action = createIntropyIntCreateAction({ config: makeConfig() });
152	    await expect(
153	      action.handler(makeCtx({ blueprint: 'hello-world', name: 'MyApi' })),
154	    ).rejects.toThrow(/exit 1/);
155	  });
156	
157	  it('rejects a targetPath that escapes the workspace', async () => {
158	    const action = createIntropyIntCreateAction({ config: makeConfig() });
159	    await expect(
160	      action.handler(
161	        makeCtx({
162	          blueprint: 'hello-world',
163	          name: 'MyApi',
164	          targetPath: '../../etc',
165	        }),
166	      ),
167	    ).rejects.toThrow();
168	    expect(mockRun).not.toHaveBeenCalled();
169	  });
170	});

1	import { createTemplateAction } from '@backstage/plugin-scaffolder-node';
2	import {
3	  resolveSafeChildPath,
4	  RootConfigService,
5	} from '@backstage/backend-plugin-api';
6	import { InputError } from '@backstage/errors';
7	import fs from 'fs-extra';
8	import path from 'node:path';
9	import { runIntropyCli } from './runIntropyCli';
10	
11	export const intropyIntCreateExamples = [
12	  {
13	    description: 'Scaffold an integration from a blueprint',
14	    example: `
15	steps:
16	  - id: create
17	    action: intropy:int:create
18	    input:
19	      blueprint: hello-world
20	      name: MyApi
21	      targetPath: ./output/integrations/my-api
22	      values:
23	        someBlueprintParam: value
24	`,
25	  },
26	];
27	
28	/** Shape of the CLI's --output-json CreateResult. Parsed defensively. */
29	interface CreateResult {
30	  blueprint?: string;
31	  version?: string;
32	  outputDir?: string;
33	}
34	
35	/**
36	 * Creates the intropy:int:create action.
37	 *
38	 * Runs `intropy int create <blueprint>` inside the scaffolder workspace to
39	 * generate an integration. The CLI is the single source of scaffolding logic;
40	 * this action just adapts it to the Backstage scaffolder (workspace-relative
41	 * paths, structured errors, and registered outputs).
42	 */
43	export function createIntropyIntCreateAction(options: {
44	  config: RootConfigService;
45	}) {
46	  const { config } = options;
47	
48	  return createTemplateAction({
49	    id: 'intropy:int:create',
50	    description:
51	      'Scaffolds an integration by running the intropy CLI (int create) against a blueprint.',
52	    examples: intropyIntCreateExamples,
53	    schema: {
54	      input: {
55	        blueprint: z => z.string().describe('Blueprint id, e.g. hello-world'),
56	        name: z => z.string().describe('Name of the integration to create'),
57	        targetPath: z =>
58	          z
59	            .string()
60	            .optional()
61	            .describe(
62	              'Workspace-relative directory to generate into. Defaults to the workspace root.',
63	            ),
64	        values: z =>
65	          z
66	            .record(z.any())
67	            .optional()
68	            .describe('Blueprint parameter values (may be nested).'),
69	      },
70	      output: {
71	        outputDir: z =>
72	          z
73	            .string()
74	            .describe('Workspace-relative path of the generated integration.'),
75	        blueprintVersion: z =>
76	          z.string().describe('Resolved blueprint version.'),
77	        blueprint: z => z.string().describe('Resolved blueprint id.'),
78	      },
79	    },
80	    async handler(ctx) {
81	      const { blueprint, name, targetPath, values } = ctx.input;
82	
83	      const outDir = resolveSafeChildPath(ctx.workspacePath, targetPath ?? '.');
84	      await fs.ensureDir(outDir);
85	
86	      // Values and the result file go in an auto-cleaned temp dir so they never
87	      // land in the published workspace.
88	      const tmpDir = await ctx.createTemporaryDirectory();
89	      const resultPath = path.join(tmpDir, 'result.json');
90	
91	      const args = [
92	        'int',
93	        'create',
94	        blueprint,
95	        '--output',
96	        outDir,
97	        '--name',
98	        name,
99	        '--no-input',
100	        '--skip-install-skills',
101	        '--output-json',
102	        resultPath,
103	      ];
104	
105	      // JSON is a strict subset of YAML, so the CLI's -f parser accepts it and
106	      // we avoid --set string-flattening of nested values.
107	      if (values && Object.keys(values).length > 0) {
108	        const valuesPath = path.join(tmpDir, 'values.json');
109	        await fs.writeFile(valuesPath, JSON.stringify(values, null, 2), 'utf8');
110	        args.push('-f', valuesPath);
111	      }
112	
113	      const cliPath = config.getOptionalString('intropy.cli.path') ?? 'intropy';
114	
115	      ctx.logger.info(
116	        `Running intropy int create ${blueprint} (name: ${name})`,
117	      );
118	
119	      const { exitCode, stderrTail } = await runIntropyCli({
120	        command: cliPath,
121	        args,
122	        cwd: ctx.workspacePath,
123	        env: { ...process.env },
124	        logger: ctx.logger,
125	      });
126	
127	      if (exitCode === 2) {
128	        throw new InputError(
129	          `intropy rejected the input for blueprint '${blueprint}' (usage error). ` +
130	            `Check that all required blueprint parameters are provided.\n${stderrTail.join(
131	              '\n',
132	            )}`,
133	        );
134	      }
135	      if (exitCode !== 0) {
136	        throw new Error(
137	          `intropy int create failed (exit ${exitCode}).\n${stderrTail.join(
138	            '\n',
139	          )}`,
140	        );
141	      }
142	
143	      let result: CreateResult = {};
144	      try {
145	        result = JSON.parse(await fs.readFile(resultPath, 'utf8'));
146	      } catch (err) {
147	        ctx.logger.warn(
148	          `intropy succeeded but its --output-json result could not be read: ${err}`,
149	        );
150	      }
151	
152	      // The CLI reports an absolute outputDir; downstream steps (fs, publish)
153	      // need it relative to the workspace. Fall back to the requested outDir.
154	      const absOutputDir = result.outputDir ?? outDir;
155	      const relOutputDir = path.relative(ctx.workspacePath, absOutputDir);
156	      if (relOutputDir.startsWith('..') || path.isAbsolute(relOutputDir)) {
157	        throw new Error(
158	          `intropy wrote outside the workspace (${absOutputDir}); refusing to continue.`,
159	        );
160	      }
161	
162	      ctx.output('outputDir', relOutputDir);
163	      ctx.output('blueprintVersion', result.version ?? 'unknown');
164	      ctx.output('blueprint', result.blueprint ?? blueprint);
165	
166	      ctx.logger.info(
167	        `Created ${result.blueprint ?? blueprint}@${
168	          result.version ?? 'unknown'
169	        } at ${relOutputDir}`,
170	      );
171	    },
172	  });
173	}

