import React from 'react';
import { useParams } from 'react-router-dom';
import useAsync from 'react-use/lib/useAsync';
import {
  Content,
  ContentHeader,
  Header,
  InfoCard,
  Link,
  Page,
  Progress,
  ResponseErrorPanel,
  StructuredMetadataTable,
} from '@backstage/core-components';
import { Grid } from '@material-ui/core';
import { useApi, useRouteRef } from '@backstage/core-plugin-api';
import { agentSkillsApiRef } from '../../api';
import { rootRouteRef } from '../../routes';

export const SkillDetailPage = () => {
  const { ref = '' } = useParams();
  const api = useApi(agentSkillsApiRef);
  const rootRoute = useRouteRef(rootRouteRef);
  const decoded = decodeURIComponent(ref);
  const { value, loading, error } = useAsync(
    () => api.getSkill(decoded),
    [api, decoded],
  );

  const title =
    value?.config?.name ??
    value?.annotations['io.agentskills.skill.name'] ??
    'Skill';
  const sourceUrl = value?.annotations['org.opencontainers.image.source'];

  return (
    <Page themeId="tool">
      <Header title={title} subtitle={decoded} />
      <Content>
        <ContentHeader title={value?.config?.description ?? ''}>
          <Link to={rootRoute()}>← All collections</Link>
        </ContentHeader>
        {loading && <Progress />}
        {error && <ResponseErrorPanel error={error} />}
        {value && (
